export function validateProfile(profile){const errors={};if(!profile?.displayName?.trim())errors.displayName="Enter a name or nickname.";if(!profile?.primaryGoal)errors.primaryGoal="Choose a primary goal.";if(profile?.secondaryGoal&&profile.secondaryGoal===profile.primaryGoal)errors.secondaryGoal="Choose a different secondary goal.";if(!profile?.fitnessExperience)errors.fitnessExperience="Choose an experience level.";if(!profile?.assessmentFamiliarity)errors.assessmentFamiliarity="Choose how familiar you are with assessment terms.";return errors}
export function validateAssessment(assessment){const errors={};for(const id of ["weight","pbf","smm"]){const metric=assessment?.metrics?.find(item=>item.id===id);if(!metric||metric.value===""||!Number.isFinite(Number(metric.value)))errors[id]="Enter a valid number."}return errors}
